class Solution {
public:
    long long minCost(std::vector<int>& nums, std::vector<int>& cost) {
        int n = nums.size();
        std::vector<std::pair<long long, long long>> pairs(n);
        long long total_weight = 0;
        for (int i = 0; i < n; i++) {
            pairs[i] = {nums[i], cost[i]};
            total_weight += cost[i];
        }
        std::sort(pairs.begin(), pairs.end());

        long long half = (total_weight + 1) / 2;
        long long acc = 0, target = 0;
        for (const auto& [x, w] : pairs) {
            acc += w;
            if (acc >= half) {
                target = x;
                break;
            }
        }

        long long ans = 0;
        for (const auto& [x, w] : pairs) {
            ans += std::abs(x - target) * w;
        }
        return ans;
    }
};

class Solution {
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        long[][] pairs = new long[n][2];
        long totalWeight = 0;
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = cost[i];
            totalWeight += cost[i];
        }
        java.util.Arrays.sort(pairs, (a, b) -> Long.compare(a[0], b[0]));

        long half = (totalWeight + 1) / 2;
        long acc = 0, target = 0;
        for (long[] p : pairs) {
            acc += p[1];
            if (acc >= half) {
                target = p[0];
                break;
            }
        }

        long ans = 0;
        for (long[] p : pairs) {
            ans += Math.abs(p[0] - target) * p[1];
        }
        return ans;
    }
}

var minCost = function(nums, cost) {
    const pairs = nums.map((x, i) => [BigInt(x), BigInt(cost[i])]);
    pairs.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

    let totalWeight = 0n;
    for (const [, w] of pairs) totalWeight += w;

    const half = (totalWeight + 1n) / 2n;
    let acc = 0n, target = 0n;
    for (const [x, w] of pairs) {
        acc += w;
        if (acc >= half) {
            target = x;
            break;
        }
    }

    let ans = 0n;
    for (const [x, w] of pairs) {
        const diff = x > target ? x - target : target - x;
        ans += diff * w;
    }
    return Number(ans);
};
